-- Postgres schema generated from portable-schema.sql (same tables, same columns).
CREATE OR REPLACE FUNCTION ledger_immutable() RETURNS trigger AS $$ BEGIN RAISE EXCEPTION 'ledger_immutable'; END $$ LANGUAGE plpgsql;
CREATE TABLE IF NOT EXISTS participants(id TEXT PRIMARY KEY,nationalId TEXT UNIQUE,name TEXT,passwordHash TEXT,recoveryPhone TEXT,institution TEXT,track TEXT DEFAULT 'easy',nextTrack TEXT,trackEffective TEXT,balance INTEGER DEFAULT 0 CONSTRAINT nonnegative_balance CHECK(balance>=0),blocked INTEGER DEFAULT 0,createdAt TEXT);
CREATE TABLE IF NOT EXISTS exams(id TEXT PRIMARY KEY,title TEXT,materialKey TEXT,week TEXT,track TEXT,kind TEXT,opensAt TEXT,closesAt TEXT,questionCount INTEGER,questions TEXT,published INTEGER DEFAULT 0,createdAt TEXT);
CREATE TABLE IF NOT EXISTS attempts(id TEXT PRIMARY KEY,participantId TEXT REFERENCES participants(id),examId TEXT REFERENCES exams(id),materialKey TEXT,snapshot TEXT,completed INTEGER DEFAULT 0,score INTEGER DEFAULT 0,createdAt TEXT,completedAt TEXT,UNIQUE(participantId,materialKey));
CREATE TABLE IF NOT EXISTS answers(id TEXT PRIMARY KEY,attemptId TEXT REFERENCES attempts(id),questionId TEXT,choice INTEGER,points INTEGER,createdAt TEXT,UNIQUE(attemptId,questionId));
CREATE TABLE IF NOT EXISTS ledger(id TEXT PRIMARY KEY,participantId TEXT REFERENCES participants(id),delta INTEGER,reason TEXT,reference TEXT UNIQUE,actor TEXT,createdAt TEXT);
CREATE OR REPLACE FUNCTION ledger_apply_fn() RETURNS trigger AS $$ BEGIN UPDATE participants SET balance=balance+NEW.delta WHERE id=NEW.participantId; RETURN NEW; END $$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS ledger_apply ON ledger; CREATE TRIGGER ledger_apply AFTER INSERT ON ledger FOR EACH ROW EXECUTE FUNCTION ledger_apply_fn();
DROP TRIGGER IF EXISTS ledger_no_update ON ledger; CREATE TRIGGER ledger_no_update BEFORE UPDATE ON ledger FOR EACH ROW EXECUTE FUNCTION ledger_immutable();
DROP TRIGGER IF EXISTS ledger_no_delete ON ledger; CREATE TRIGGER ledger_no_delete BEFORE DELETE ON ledger FOR EACH ROW EXECUTE FUNCTION ledger_immutable();
CREATE TABLE IF NOT EXISTS benefits(id TEXT PRIMARY KEY,title TEXT,merchant TEXT,branch TEXT,kind TEXT,cost INTEGER CHECK(cost>0),faceValue INTEGER DEFAULT 0,opensAt TEXT,closesAt TEXT,redeemUntil TEXT,delivery TEXT DEFAULT 'export',active INTEGER DEFAULT 1,createdAt TEXT);
CREATE TABLE IF NOT EXISTS cards(id TEXT PRIMARY KEY,participantId TEXT REFERENCES participants(id),network TEXT,number TEXT,approved INTEGER DEFAULT 1,createdAt TEXT,UNIQUE(participantId,network));
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY,participantId TEXT REFERENCES participants(id),benefitId TEXT REFERENCES benefits(id),quantity INTEGER CHECK(quantity>0),total INTEGER,cardNumber TEXT,status TEXT,code TEXT UNIQUE,requestKey TEXT UNIQUE,snapshot TEXT,createdAt TEXT,exportedAt TEXT,completedAt TEXT);
CREATE TABLE IF NOT EXISTS audit(id TEXT PRIMARY KEY,actor TEXT,action TEXT,target TEXT,details TEXT,createdAt TEXT);
CREATE TABLE IF NOT EXISTS sessions(tokenHash TEXT PRIMARY KEY,participantId TEXT REFERENCES participants(id),expiresAt TEXT);
CREATE TABLE IF NOT EXISTS auth_limits(key TEXT PRIMARY KEY,failures INTEGER DEFAULT 0,until TEXT);
CREATE TABLE IF NOT EXISTS messages(id TEXT PRIMARY KEY,participantId TEXT REFERENCES participants(id),subject TEXT,body TEXT,audioKey TEXT,reply TEXT,replyAudioKey TEXT,status TEXT DEFAULT 'open',createdAt TEXT);
CREATE TABLE IF NOT EXISTS staff(userId TEXT PRIMARY KEY,name TEXT,role TEXT,scope TEXT,createdAt TEXT);
CREATE TABLE IF NOT EXISTS legacy(id TEXT PRIMARY KEY,source TEXT,rowKey TEXT UNIQUE,nationalId TEXT,kind TEXT,payload TEXT,createdAt TEXT);
CREATE TABLE IF NOT EXISTS shipments(id TEXT PRIMARY KEY,participantId TEXT REFERENCES participants(id),kind TEXT,address TEXT,status TEXT DEFAULT 'pending',notes TEXT,createdAt TEXT);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT);
