CREATE TABLE IF NOT EXISTS b_answers(id TEXT PRIMARY KEY,attemptId TEXT REFERENCES b_attempts(id),questionId TEXT,choice INTEGER,points INTEGER,createdAt TEXT,UNIQUE(attemptId,questionId));
CREATE TABLE IF NOT EXISTS b_ledger(id TEXT PRIMARY KEY,participantId TEXT REFERENCES b_participants(id),delta INTEGER,reason TEXT,reference TEXT UNIQUE,actor TEXT,createdAt TEXT);
CREATE OR REPLACE FUNCTION b_ledger_apply_fn() RETURNS trigger AS $$ BEGIN UPDATE b_participants SET balance=balance+NEW.delta WHERE id=NEW.participantId; RETURN NEW; END $$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS b_ledger_apply ON b_ledger; CREATE TRIGGER b_ledger_apply AFTER INSERT ON b_ledger FOR EACH ROW EXECUTE FUNCTION b_ledger_apply_fn();
DROP TRIGGER IF EXISTS b_ledger_no_update ON b_ledger; CREATE TRIGGER b_ledger_no_update BEFORE UPDATE ON b_ledger FOR EACH ROW EXECUTE FUNCTION ledger_immutable();
DROP TRIGGER IF EXISTS b_ledger_no_delete ON b_ledger; CREATE TRIGGER b_ledger_no_delete BEFORE DELETE ON b_ledger FOR EACH ROW EXECUTE FUNCTION ledger_immutable();
